import{_ as e,o as r,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Developer Monthly 2023-12-06","description":"","frontmatter":{"title":"Ceph Developer Monthly 2023-12-06","date":"2023-12-06T00:00:00.000Z","updated":"2023-12-14T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏纠正码","复制","快照","克隆","瘦分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Developer_Monthly_2023-12-06.md","filePath":"posts/2023/Ceph_Developer_Monthly_2023-12-06.md","lastUpdated":1780460162000}'),a={name:"posts/2023/Ceph_Developer_Monthly_2023-12-06.md"};function l(s,t,p,i,g,_){return r(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph Manager模块加载问题讨论</p><p><strong>参会人员：</strong> Ilia, Gas, Ramina, Radic, Patrick, Travis</p><p><strong>会议时间：</strong> [未提供具体时间]</p><p><strong>会议地点：</strong> 视频会议</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>问题描述：</strong></p><ul><li>在Ceph Manager启动时，所有Manager模块会被加载，命令被发现。由于命令的发现和命令注册的过程是分开的，当Manager接收到一个命令时，可能尚未加载完成，导致错误。</li></ul></li><li><p><strong>讨论议题：</strong></p><ul><li><strong>错误处理：</strong> 讨论了客户端在Manager模块未完全加载时接收到的错误信息，以及如何处理这些错误。</li><li><strong>模块加载同步性：</strong> 讨论了是否应该让模块加载过程同步，并在模块完全加载后再执行相关命令。</li><li><strong>可用性标志（available flag）：</strong> 讨论了Manager Map中的可用性标志的实际意义和如何改进其使用。</li></ul></li><li><p><strong>决定事项：</strong></p><ul><li><strong>模块加载策略：</strong> 决定重新审视Mola的修复方案，考虑在Manager响应后异步加载Python模块，并延迟设置可用性标志，直到所有模块加载完成。</li><li><strong>客户端等待机制：</strong> 决定客户端在执行命令前应检查模块是否真正可用，并在Manager Map中等待可用状态。</li></ul></li><li><p><strong>后续行动计划：</strong></p><ul><li><strong>实施细节讨论：</strong> 需要进一步讨论具体的实施细节，包括是否修复现有的可用性标志或添加新的标志。</li><li><strong>征求反馈：</strong> 需要将讨论结果总结并征求Patrick和Travis的反馈，特别是关于Manager Map的使用和外部用户的兼容性问题。</li><li><strong>文档更新：</strong> 需要更新文档，明确Manager模块启用命令的异步性质，并指导用户如何正确等待模块可用。</li></ul></li></ol><p><strong>会议结束：</strong> 会议在讨论完所有议题后结束，未有新的议题提出。</p><p><strong>备注：</strong> 由于部分关键人员（如Patrick和n）未参会，会议决定在后续的PR评论中征求他们的意见，并确保所有相关方都了解并同意最终的实施方案。</p>',9)])])}const c=e(a,[["render",l]]);export{h as __pageData,c as default};
